package com.hrflow.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.Key;import java.util.*;
@Service public class JwtService { @Value("${app.jwt.secret}") String secret; @Value("${app.jwt.expiration-ms}") long expiration; private Key key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(Long id,String email,String role){return Jwts.builder().subject(email).claim("uid",id).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key()).compact();} public Claims claims(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key()).build().parseSignedClaims(token).getPayload();} public boolean valid(String token){try{claims(token);return true;}catch(Exception e){return false;}} }
